signature.advancedArgs:
{
  "type": "object",
  "properties": {
    "showTab": {
      "type": "string",
      "description": "Set when the user asks to see the dates on one tab of the Manual In and Out screen - e.g. 'what are the dates in the pending tab'. Pass the tab name as the user says it: Regularize, Pending, Valid Swipes or Off Shifts. No date is needed (the team and admin tools still need the employee). Returns only that tab's dates and submits nothing - show the dates as returned."
    },
    "listSubordinates": {
      "type": "boolean",
      "description": "Set to true when the user asks to see the team members (subordinates) they can submit manual In and Out for - e.g. \"display all the subordinates I can apply manual In and Out for\". No employee or date is needed; the tool returns the list (number and name) and submits nothing. Show the list, then ask which one and the date."
    },
    "employeeNumber": {
      "type": "string",
      "description": "The team member's employee number, e.g. 000017. Leading zeros are optional. Either employeeNumber or employeeName must be given - ask the user which team member if neither is known."
    },
    "employeeName": {
      "type": "string",
      "description": "The team member's name, full or partial. Either employeeNumber or employeeName must be given. If it matches more than one person the tool returns candidates - ask the user which one, never pick."
    },
    "fieldsToEdit": {
      "type": "array",
      "items": {
        "enum": [
          "inDate",
          "inTime",
          "outDate",
          "outTime"
        ]
      },
      "description": "What the user wants to change. After showing the recorded In and Out (the tool lists them under editableFields), ask the user which they want to edit - In Date, In Time, Out Date or Out Time, one or more - and pass their choice here. The tool then asks for the new values of only those. Fields not chosen keep their recorded values."
    },
    "date": {
      "type": "string",
      "description": "The day of the recorded manual In and Out to edit, in the format returned by the dateFormat tool (MM/DD/YYYY for en-US, otherwise DD/MM/YYYY). Ask the user for it, then call the tool straight away with the employee and the date alone - the tool checks which tab the day is on and returns the shift details and what is recorded before anything else is asked. Also call with the date when the user asks for the status of a pending request on that date - for a Pending day the tool returns the status, what was requested (old -> new In/Out and break times), the comment and who it is waiting for (pendingRequest); show that as returned."
    },
    "inDate": {
      "type": "string",
      "description": "New In date, in the format returned by the dateFormat tool. Pass it only when the user chose to edit the In Date; otherwise the recorded In date is kept."
    },
    "inTime": {
      "type": "string",
      "description": "New In time in HH:mm 24-hour format, e.g. 08:30. Pass it only when the user chose to edit the In Time; otherwise the recorded In time is kept."
    },
    "outDate": {
      "type": "string",
      "description": "New Out date, in the format returned by the dateFormat tool. Pass it only when the user chose to edit the Out Date; otherwise the recorded Out date is kept. An Out Date on the day AFTER the In Date is normal - many shifts end after midnight - and must never be questioned; never decide it yourself."
    },
    "outTime": {
      "type": "string",
      "description": "New Out time in HH:mm 24-hour format, e.g. 17:30. Pass it only when the user chose to edit the Out Time; otherwise the recorded Out time is kept. An Out time earlier on the clock than the In time is normal when the Out Date is the following day."
    },
    "clearInTime": {
      "type": "boolean",
      "description": "Set to true when the user wants to remove (clear) the recorded In time, as the Valid Swipes grid allows - e.g. 'delete my in time for 05/11/2024'. Do not also give inTime. Needs a reason; the day is submitted with the In empty."
    },
    "clearOutTime": {
      "type": "boolean",
      "description": "Set to true when the user wants to remove (clear) the recorded Out time. Do not also give outTime. Can be combined with clearInTime to clear both. Needs a reason."
    },
    "deleteBreaks": {
      "type": "array",
      "items": {
        "type": "integer"
      },
      "description": "Numbers (breakNo, from shiftDetails.recordedBreaks) of the recorded breaks the user wants to delete - e.g. [1]. Deleting breaks alone is a valid edit; it needs a reason. Do not also change the same break in breaks."
    },
    "reason": {
      "type": "string",
      "description": "Reason/comment explaining why the manual In and Out is being changed. Required before the update is submitted."
    },
    "breaks": {
      "type": "array",
      "description": "Optional breaks - none, one or as many as the user wants. After showing the recorded values, tell the user they can add breaks or change a recorded one (shiftDetails.recordedBreaks, numbered by breakNo), but do not insist. Each break needs both times and must sit within the In and Out date-times and the shift's allowed period. A break after midnight is fine on a shift whose period reaches there.",
      "items": {
        "type": "object",
        "properties": {
          "breakInTime": {
            "type": "string",
            "description": "Break start time in HH:mm 24-hour format, e.g. 12:00."
          },
          "breakOutTime": {
            "type": "string",
            "description": "Break end time in HH:mm 24-hour format, e.g. 13:00."
          },
          "breakNo": {
            "type": "integer",
            "description": "Only to CHANGE a recorded break: its breakNo from shiftDetails.recordedBreaks. Leave it out to add a new break."
          }
        },
        "required": [
          "breakInTime",
          "breakOutTime"
        ]
      }
    },
    "breakInTime": {
      "type": "string",
      "description": "Single-break shorthand: break start time in HH:mm (adds a new break). Prefer the breaks list. If given, breakOutTime must be given too."
    },
    "breakOutTime": {
      "type": "string",
      "description": "Single-break shorthand: break end time in HH:mm (adds a new break). Prefer the breaks list. If given, breakInTime must be given too."
    },
    "otherEntries": {
      "type": "array",
      "description": "When the user asks for several days in one request, pass on every call the OTHER days of that request that are not submitted yet, each with the values the user gave. The screen submits such days together and refuses all of them when two overlap across midnight, so the tool checks the overlap in each day's preview. Preview every day first; submit none until all previews passed.",
      "items": {
        "type": "object",
        "properties": {
          "date": {
            "type": "string",
            "description": "That day, in the dateFormat format."
          },
          "inDate": {
            "type": "string"
          },
          "inTime": {
            "type": "string",
            "description": "HH:mm"
          },
          "outDate": {
            "type": "string"
          },
          "outTime": {
            "type": "string",
            "description": "HH:mm"
          }
        }
      }
    },
    "confirmed": {
      "type": "boolean",
      "description": "Set to true, together with previewToken, only after the user has reviewed the preview of current vs new values (it names the team member) and explicitly confirmed. Set to false (or omit) to preview/validate without updating anything. Never send it on the first call - the tool validates and returns the preview first."
    },
    "previewToken": {
      "type": "string",
      "description": "The previewToken from the preview the user confirmed. Required with confirmed:true. Without it, or if any value changed since that preview, nothing is submitted and the preview is returned again - show it and ask for confirmation."
    },
    "isGroupByEmployee": {
      "type": "boolean",
      "description": "Optional Group By Employee checkbox on the Search Criteria panel. Omit it to use the screen's own default."
    },
    "rosterGroup": {
      "type": "string",
      "description": "Optional roster group, by id or name. Omit it to use the screen's first roster group. Do not ask the user for it unless they want a specific roster."
    },
    "rosterCode": {
      "type": "string",
      "description": "Optional roster code. Takes precedence over rosterName. Omit it to use the first roster of the roster group, as the screen does."
    },
    "rosterName": {
      "type": "string",
      "description": "Optional roster name. Resolved to a roster code within the roster group. Ignored when rosterCode is given."
    }
  },
  "required": []
}
